-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per bill the company owes: vendor bills and people's expense reports (IsExpenseReport). Voided ones included (StatusCode VOID). Needs ap.view.
CREATE VIEW rpt.Bill
AS
SELECT
    b.Id AS BillId,
    b.BillNumber AS BillNumber,
    CONVERT(BIT, IIF(b.PayeeUserId IS NULL, 0, 1)) AS IsExpenseReport,
    b.VendorId AS VendorId,
    COALESCE(v.Name, u.DisplayName) AS PayeeName,
    b.VendorInvoiceNumber AS VendorInvoiceNumber,
    b.BillDate AS BillDate,
    b.DueDate AS DueDate,
    s.Name AS Status,
    s.SystemCode AS StatusCode,
    b.Description AS Description,
    b.SubTotal AS SubTotal,
    b.TaxAmount AS TaxAmount,
    b.Total AS Total,
    b.AmountPaid AS AmountPaid,
    b.BalanceDue AS BalanceDue,
    IIF((s.SystemCode = 'OPEN' OR s.SystemCode = 'PARTIAL') AND b.BalanceDue > 0 AND b.DueDate < CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE), DATEDIFF(DAY, b.DueDate, CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE)), 0) AS DaysPastDue
FROM ap.Bill AS b
JOIN lkp.BillStatus AS s ON s.TenantId = b.TenantId AND s.Id = b.BillStatusId
JOIN admin.Tenant AS tn ON tn.Id = b.TenantId
LEFT JOIN ap.Vendor AS v ON v.TenantId = b.TenantId AND v.Id = b.VendorId
LEFT JOIN sec.AppUser AS u ON u.TenantId = b.TenantId AND u.Id = b.PayeeUserId
WHERE EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(b.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'ap.view'));
GO
